    for curr in path[1:]:
        product *= tree[curr]
    return product % k

def check_path_correctness(edges, k, left, right, current_path):
    if len(current_path) == 3:
        path1 = [left, current_path[0]] + sorted(current_path)
        path2 = [right, current_path[1]] + sorted(current_path)
        if calculate_paths(tree, k, path1) * calculate_paths(tree, k, [k] + path2) % k == 1:
            return True
        else:
            return False
    for neighbor in tree[current_path[-1]]:
        if neighbor != right:
            if check_path_correctness(edges, k, left, right, current_path + [neighbor]):
                return True
    return False

def solution(n, y, k, edges, tree, v):
    global tree
    tree = tree
    graph, k = construct_graph(n, edges, k)
    left = sum(v) // k
    right = sum(v) // k + 1
