from heapq import heappop, heappush

def dijkstra(n, edges, start):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append((v-1, min(u, v)))
        graph[v-1].append((u-1, min(u, v)))

    distances = [float('inf')] * n
    distances[start-1] = 0
    priority_queue = [(0, [start-1])]
    while priority_queue:
        current_distance, current_path = heappop(priority_queue)
        if current_distance > distances[current_path[-1]]:
            continue
        for neighbor, distance in graph[current_path[-1]]:
            new_distance = current_distance + distance
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                heappush(priority_queue, (new_distance, list(current_path) + [neighbor]))
    return distances

def solve(hotels, queries):
    invariants = {}
    for i in range(hotels-1):
        for j in range(i+1, hotels):
            if i == 1:
                invariants[j] = j if j > i and j > 1 else i
            else:
                invariants[j] = invariants[i+1] if i+j <= hotels-i-1 else j
    result = []
    for i, j in queries:
        if invariants.get(i) != j:
            print('WA\ninvariants')
            return
        result.append(dijkstra(hotels, list(map(lambda x: invariants[x] - 1, range(hotels))), j))
    return result

