                    seen_of_myself.add(a_i)

            prev_another = a_i

        new_sum = (
            (1 << free_positions) - 1
            ^ recursive_sum(start + 1, seen_of_myself)
            | (total_sum ^ seen_of_myself - set(friends_attractiveness[start])) ** 2
        )
        return new_sum

    free_positions = n - m
    # Take the XOR of every odd position with its own values, if we can take it.
    return recursive_sum(0, set()).mod(1000000007)

