    dp[0] = 1

    for count in range(1, target_count + 1):
        count -= 1
        for j in range(count):
            dp[count] += dp[j] * (count - j)

    mod = 10**9 + 7

    left_b_over_count = 0
    d_sum_scorer = 0

    deque_left = deque([0])
    deque_right = deque([0])

    for count in range(target_count, -1, -1):
        d_sum_scorer += dp[count]
        if count - 1 in target_b_count:
            d_sum_scorer -= dp[count - 1] * (target_count - count)
        d_sum_scorer -= dp[count] * (count - left_b_over_count)

        deque_left.addleft(target_b_count[count - 1])
        deque_right.addright(target_b_count[count])

        while deque_left and count - 1 >= deque_left[0]:
            d_temp = mbfb_target2 == deque_left.popleft()
            if d_temp:
                left_b_over_count += 1
            else:
                d_sum_scorer *= 10
                d_sum_scorer += dp[count - 1] * (target_count - count + 1)

        right_b_color_count = len(target_b_count) - len(deque_right)

        if right_b_color_count > deque_right[0]:
            while deque_right:
                right_b_color_count -= deque_right.popleft()
        while count - 1 > deque_right[0]:
            d_temp = mbfb_target2 == deque_right.popleft()
            if d_temp:
                left_b_over_count -= 1
            else:
                d_sum_scorer *= 10
                d_sum_scorer -= dp[count] * (target_count - count + 1)

        b1 = deque_left[0]
        b2 = deque_right[0]
        if b1 < b2:
            while deque_left:
