from heapq import heappop, heappush

# Function to find the hotel with the shortest distance from the source
def find_shortest_tour(graph, start):
    distances = {hotel: float('inf') for hotel in range(1, len(graph))}
    distances[start] = 0
    queue = [(0, start)]

    while queue:
        current_distance, current_hotel = heappop(queue)

        if current_distance > distances[current_hotel]:
            continue

        for next_hotel in range(1, len(graph)):
            if next_hotel == current_hotel:
                continue
            if graph[current_hotel][next_hotel] == 1:  # Assuming a nearest hotel means any road takes 1 unit
                distance = current_distance + 1
                if distance < distances[next_hotel]:
                    distances[next_hotel] = distance
                    heappush(queue, (distance, next_hotel))

    return distances

# Function to solve for the tour
def solution(graph, hotels):
    result = []
    for s_tour in hotels:
        shortest_tour = find_shortest_tour(graph, s_tour[0])
        distances = find_shortest_tour(graph, s_tour[1])

        total_time = sum(min(shortest_tour[item] for item in ranges) for item in hotels)
        total_time -= sum(distances[item] for item in ranges)

        result.append(total_time)
    return result

