def min_presidios(colors, n):
    if n == 1:
        return [1]

    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    dp[1] = 1

    for k in range(2, n + 1):
        for i in range(n):
            tiles = k
            for j in range(i, n):
                if is_valid_tiles(colors, tiles):
                    dp[k] = min(dp[k], dp[tiles] + 1)
                    tiles -= 1

        if n - 1 < k:
            break

    return dp

def is_valid_tiles(colors, tiles):
    for i in range(colors.count(1) + 1):
        if i == tiles:
            continue
        for j in range(colors.count(i + 1) + 1):
            if i + j == tiles:
                continue
            for k in range(colors.count(i + j) + 1):
                if i + j + k == tiles:
                    continue
                if i < (colors.count(colors[j]) + 2):
                    return True
    return False

