def calculate_optimal_max(grid, N, M):
    # Heuristic: if the top-left element is known, we can calculate the maximum value
    optimal_max = grid[0][0]
    for i in range(1, N):
        if grid[i][0] > optimal_max:
            optimal_max = grid[i][0]
        grid[i][0] = optimal_max
    for j in range(1, M):
        if grid[0][j] > optimal_max:
            optimal_max = grid[0][j]
        grid[0][j] = optimal_max

    # floyd warshall
    for k in range(1, N + M):
        for i in range(1, N - k + 1):
            for j in range(1, M - k + 1):
                grid[i-1][j-1] = max(grid[i-1][j-1], grid[i-1][j] + grid[i][j-1])

    return grid[N-1][M-1]

