    count_a = [0] * n
    count_b = [0] * n
    for i in range(1, n):
        if A[i] > A[i-1]:
            count_b[i-1] = 1
    for i in range(n-2, -1, -1):
        if A[i] > A[i+1]:
            count_b[n-i-2] = 1
    for i in range(n):
        if A[i] != B[i]:
            count_a[i] = 1
    operations = 0
    for i in range(n):
        while A[i] > B[i] and count_a[i] == 1:
            count_a[i] = 0
            count_b[i] += 1
            operations += 1
        if B[i] > A[i] - count_a[i] and count_b[i] == 0:
            return -1
    return operations

