def is_tree_possible(n, constraints):
    if n % 2 == 0:
        return "IMPOSSIBLE"
    constraints.sort(key=lambda x: x[0])
    lefts = [x[1] for x in constraints if x[1] % 2 == 1]
    rights = [x[1] for x in constraints if x[1] % 2 == 0]
    stack = []
    for i in range(1, n + 1):
        if not stack:
            stack.append(i)
            continue
        j = i
        while stack and (not j % 2) and (lefts or rights):
            if not stack:
                stack.append(lefts.pop())
                continue
            if stack[-1] < stack[-2]:
                stack.append(j)
            else:  # Stack[-1] > stack[-2]:
                j = stack.pop()
        stack.append(i)
    return " ".join(map(str, stack))

