from math import floor, sqrt

def behavior_of_ball(n, m, x, y, vx, vy):
    if vx == 0 and vy == 0:
        return "1 0", "(1, 0)"
    elif (vx, vy) == (0, 0):
        return "0 0", "(0, 0)"

    if (vx, vy) == (1, 0) or (vy, vx) == (0, 1):
        # Define the line as specific to movement
        line = [(x + vx), (x - vx)]
    elif (vx, vy) == (1, 1) or (vy, vx) == (1, 1):
        # Define a 45 degree line
        line = [(floor(y) + vx), (floor(y - vx) if y - vx > 0 else floor(y + vx))]
    elif (vx, vy) == (-1, 0) or (vy, vx) == (0, -1):
        line = [(x - vx), (x + vx)]
    elif (vx, vy) == (-1, -1) or (vy, vx) == (-1, -1):
        line = [(floor(y) + vy), (floor(y - vy) if y - vy > 0 else floor(y + vy))]

    # Check if the line intersects the 4 pockets
    pockets = {(1, 0), (0, 1), (1, 1), (0, 0)}
    for p in pockets:
        if abs(line[-1][p] - line[0][p]) <= 1:
            return str(line[0][p]), str(line[0][p])
    return -1


