def build_tree(preorder, constraints):
    if len(preorder) == 1:
        return [preorder[0]]

    for constraint in constraints:
        if constraint[0] < constraint[1]:
            left_subtree = build_tree([preorder[i] for i in range(len(preorder)) if preorder[i] < constraint[0]], constraints)
            right_subtree = build_tree([preorder[i] for i in range(len(preorder)) if preorder[i] >= constraint[0]][::-1], constraints)
        else:
            left_subtree = build_tree([preorder[i] for i in range(len(preorder)) if preorder[i] < constraint[1]], constraints)
            right_subtree = build_tree([preorder[i] for i in range(len(preorder)) if preorder[i] >= constraint[1]][::-1], constraints)
        if not left_subtree and not right_subtree:
            return None
        if len(left_subtree) > len(right_subtree):
            left_subtree, right_subtree = right_subtree, left_subtree
        if len(left_subtree) == len(preorder):
            return left_subtree
        if left_subtree[0] == preorder[1]:
            return left_subtree + [preorder[0]] + left_subtree[::-1]
    return None

def print_tree_in_order(tree):
    if not tree:
        return "IMPOSSIBLE"
    preorder, inorder = tree[:]
    left_subtree, right_subtree = tree[1:-1]

    if len(inorder) < len(left_subtree) or len(preorder) < len(right_subtree):
        return "IMPOSSIBLE"

    for i in range(len(left_subtree) - 1):
        if left_subtree[i] < inorder[0]:
            return "IMPOSSIBLE"

    if left_subtree == [preorder[0]]:
        return ' '.join(map(str, preorder))
    return ' '.join(map(str, inorder)) + ' ' + ' '.join(map(str, preorder))

