import collections

def can_reach_building(n, m, q, roads, li, ri, si, ti):
    path_lengths = [0] * (m + 1)
    tree = [[] for _ in range(n)]

    for u, v in roads:
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)

    def dfs(i, parent):
        path_lengths[i] = 1
        for neighbor in tree[i]:
            if neighbor != parent:
                dfs(neighbor, i)
                path_lengths[i] += max(path_lengths[neighbor], 1)

    dfs(si-1, -1)

    def can_reach_time(i, time):
        return path_lengths[i] > 1 and time > 1 or time == 0

    for i in range(n):
        for j in range(n):
            if j != i:
                if can_reach_time(j, li+1):
                    if not can_reach_time(i, ri+1):
                        print("No")
                        return
    print("Yes")

