from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, size, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
            size[rootX] += size[rootY]
        else:
            parent[rootX] = rootY
            size[rootY] += size[rootX]
            if rank[rootX] == rank[rootY]:
                rank[rootY] += 1

def detect_cycle():
    # Implementation of Union-Find Data Structure
    # See https://en.wikipedia.org/wiki/Disjoint-set_data_structure
    parent = defaultdict(int)
    rank = [0] * len(graph)
    size = [1] * len(graph)
    for i in range(len(graph) - 1):
        union(parent, rank, size, graph[i], graph[i + 1])

    undiscovered_nodes = set()
    for i in range(len(graph) - 1):
        edges = graph[i] + graph[i + 1]
        if edges in undiscovered_nodes:
            return True
        undiscovered_nodes |= {edges + graph[i], graph[i + 1] + edges}
    return False

